import{_ as d,a as r,b as e,c as o,d as a,e as n,f as s,g as l,h as i,i as h,j as p}from"./chunks/core-repo-contribution.4e790OQG.js";import{_ as b,o as g,c as u,R as c}from"./chunks/framework.CGdQ6rU-.js";const x=JSON.parse('{"title":"Web3.0 オープンソースエコシステム：中国語圏開発者の貢献インサイト","description":"","frontmatter":{"title":"Web3.0 オープンソースエコシステム：中国語圏開発者の貢献インサイト","tags":["2025 China Open Source Report"]},"headers":[],"relativePath":"ja/web3.md","filePath":"ja/web3.md","lastUpdated":1783589798000}'),m={name:"ja/web3.md"};function q(W,t,k,_,f,P){return g(),u("div",null,[...t[0]||(t[0]=[c('<h1 id="web3-0-オープンソースエコシステム-中国語圏開発者の貢献インサイト" tabindex="-1">Web3.0 オープンソースエコシステム：中国語圏開発者の貢献インサイト <a class="header-anchor" href="#web3-0-オープンソースエコシステム-中国語圏開発者の貢献インサイト" aria-label="Permalink to &quot;Web3.0 オープンソースエコシステム：中国語圏開発者の貢献インサイト&quot;">​</a></h1><h2 id="報告説明" tabindex="-1">報告説明 <a class="header-anchor" href="#報告説明" aria-label="Permalink to &quot;報告説明&quot;">​</a></h2><h3 id="研究背景" tabindex="-1">研究背景 <a class="header-anchor" href="#研究背景" aria-label="Permalink to &quot;研究背景&quot;">​</a></h3><p>本レポートは『2025 中国オープンソース年度報告』の Web3.0 インサイト編を支えるデータ分析文書であり、OpenBuild（Web3 開発者コミュニティ／教育・エコシステムプラットフォーム）と Web3insight.ai（Web3 オープンソースデータ分析プラットフォーム）が分析と執筆を担当した。</p><p>Web3.0 の基盤はオープンソースプロトコルである。Ethereum、Bitcoin、Solana を問わず、オンチェーンインフラはすべてオープンソースの形で構築、維持、進化している。中国語圏開発者、すなわち中国大陸、台湾、香港、その他の中国語コミュニティとつながりを持つ開発者が、これらのプロトコルにどの程度、どのような質で貢献しているかは、中国のオープンソースコミュニティがグローバルな技術協働に参加するうえで重要な切り口である。しかし、これまで体系的なデータとして示されることは少なかった。</p><p>本レポートは、次の三つの問いに答えることを試みる。</p><ul><li>中国語圏開発者は、グローバルな Web3.0 オープンソースプロトコルにどの程度、どのような質で貢献しているのか。</li><li>過去 5 年間で、中国語圏コミュニティによるオープンソースプロトコルの選択は、どのように構造的に移り変わったのか。</li><li>中国語圏開発者は、オープンソース貢献の深さという点でどのようなボトルネックに直面しており、それをどう突破できるのか。</li></ul><h3 id="データソース" tabindex="-1">データソース <a class="header-anchor" href="#データソース" aria-label="Permalink to &quot;データソース&quot;">​</a></h3><p><strong>主要データ：Electric Capital Open Source Developer Data</strong></p><p>Electric Capital は、Web3 分野で広く参照されるオープンソース開発者レポート／データセットを公開している組織である。Electric Capital Open Source Developer Data は、Web3.0 のオープンソース参加状況を分析するための開発者アクティビティデータであり、GitHub の commit データをもとに以下を対象としている。</p><ul><li>世界 300 万人超の開発者による、ブロックチェーン関連オープンソースリポジトリでの commit 活動</li><li>500 以上のブロックチェーンエコシステムにおける開発者の帰属</li><li>対象期間：2008 年から現在まで（本レポートでは 20260321T133239 版を使用。データは 2026 年 3 月 13 日時点）</li><li>ライセンス：CC BY 4.0（出典表示を条件に、自由な利用と二次配布が可能）</li><li>データ URL：<a href="https://data.opendevdata.org" target="_blank" rel="noreferrer">https://data.opendevdata.org</a></li></ul><p><strong>補足データ：2025 Web3.0 中国語圏開発者調査レポート</strong></p><p>OpenBuild、GCC（Global Chinese Community of Universal Digital Commons、中国語圏の Web3.0 公共財コミュニティ）、登链学院（Web3・ブロックチェーン開発者向けの中国語教育コミュニティ）、Creators（中国語圏のクリエイター／開発者コミュニティ）、OpenCAS（中国語圏のオープンソース・Web3.0 研究コミュニティ）が共同で実施し、Web3insight.ai がデータ分析を提供した。2025 年末に有効回答 220 件を収集し、中国語圏 Web3.0 開発者のキャリアパス、技術選好、収入構造、オープンソース参加状況を対象としている。本レポートでは各章でその定性的な洞察を引用し、Electric Capital の定量データと突き合わせて確認している。</p><div class="tip custom-block"><p class="custom-block-title">関連資料：OpenBuild Web3 Developer Report</p><p>本稿で引用した中国語圏開発者調査と今後の年次更新は、OpenBuild 開発者レポートサイトに継続的に整理される。完全な図表、方法論、過去版は次の URL で参照できる：<a href="https://report.openbuild.xyz/" target="_blank" rel="noreferrer">https://report.openbuild.xyz/</a></p><p>2025 中国語圏開発者レポート：<a href="https://report.openbuild.xyz/zh/2025/" target="_blank" rel="noreferrer">https://report.openbuild.xyz/zh/2025/</a></p><p>ソースリポジトリ：<a href="https://github.com/openbuildxyz/web3-chinese-speaking-devs-report" target="_blank" rel="noreferrer">https://github.com/openbuildxyz/web3-chinese-speaking-devs-report</a></p></div><h3 id="データの限界" tabindex="-1">データの限界 <a class="header-anchor" href="#データの限界" aria-label="Permalink to &quot;データの限界&quot;">​</a></h3><p><strong>地理的帰属のカバー率</strong>：Electric Capital のデータセットでは、約 87 万人の開発者（全体の約 27%）に明確な地理情報が記録されている。中国の開発者は GitHub 上で地理情報を記入する割合が欧米より著しく低いため、中国語圏開発者の統計値は体系的に低く出る。本レポートでは GitHub Octoverse などのクロスデータに基づき、中国語圏開発者の実際の規模は、記録されている数字の <strong>3-4 倍</strong> 程度と推定している。</p><p><strong>月間アクティブ開発者（MAD）の定義</strong>：MAD（monthly active developers）は、「過去 30 日以内にブロックチェーン関連のオープンソースリポジトリで少なくとも 1 回の有効な commit がある開発者」を測定基準とする。これはコア貢献者に寄った指標であり、コードの閲覧のみ、Issue の投稿、議論への参加だけを行う開発者は含まない。</p><p><strong>エコシステム帰属の方法</strong>：一人の開発者が複数のエコシステムで同時に活動することがある。こうした multichain developers（複数チェーン／プロトコルにまたがって貢献する開発者）のため、各エコシステムの開発者数の合計は全体数を上回る。本レポートの中国語圏比率などのデータは、すべて同じ集計基準で計算している。</p><p><strong>オープンソースデータが中心</strong>：主に GitHub のオープンソース貢献データに基づく。オープンソースに参加していない開発者や、Private リポジトリで貢献している開発者は統計に含まれない可能性があり、実感値とのずれが生じることがある。</p><h3 id="読み方ガイド" tabindex="-1">読み方ガイド <a class="header-anchor" href="#読み方ガイド" aria-label="Permalink to &quot;読み方ガイド&quot;">​</a></h3><table><thead><tr><th>章</th><th>中心となる問い</th></tr></thead><tbody><tr><td>第一章｜グローバル動向</td><td>Web3.0 オープンソースプロトコル貢献者の長期トレンドと専門化の度合い</td></tr><tr><td>第二章｜グローバルでの位置</td><td>中国語圏貢献者のグローバルなオープンソースプロトコルにおける実際の比率と「見えにくさ」</td></tr><tr><td>第三章｜エコシステム分布</td><td>中国語圏開発者はどのオープンソースプロトコルで最も活発に貢献しているのか</td></tr><tr><td>第四章｜選好の移行</td><td>2021-2025 年における中国語圏コミュニティのオープンソースプロトコル選択の移行パス</td></tr><tr><td>第五章｜都市分布</td><td>中国大陸の Web3.0 オープンソース貢献者の地理的構造</td></tr><tr><td>第六章｜プロトコルの健全性</td><td>主要 Web3.0 オープンソースプロトコルの貢献者健全性の全体像</td></tr><tr><td>第七章｜オープンソース貢献</td><td>中国語圏開発者の貢献深度の現状と改善パス</td></tr><tr><td>第八章｜提言と展望</td><td>開発者個人、オープンソースコミュニティ、エコシステム運営側への行動提案</td></tr></tbody></table><hr><h2 id="第一章-グローバル-web3-0-オープンソース貢献者の規模トレンド" tabindex="-1">第一章｜グローバル Web3.0 オープンソース貢献者の規模トレンド <a class="header-anchor" href="#第一章-グローバル-web3-0-オープンソース貢献者の規模トレンド" aria-label="Permalink to &quot;第一章｜グローバル Web3.0 オープンソース貢献者の規模トレンド&quot;">​</a></h2><p>オープンソースの世界では、あるプロトコルが健全かどうかは、最終的には価格動向やソーシャルメディア上の話題性ではなく、どれだけの人が継続的にコードベースへ貢献しているかで判断される。Web3.0 の基盤プロトコルはすべてオープンソースの形で運用されており、貢献者数の長期トレンドは、そのエコシステムが持続的に進化できるかを判断する中核的な指標である。</p><h3 id="_1-1-貢献者の質-2025-年のピークは-2022-年よりも堅実" tabindex="-1">1.1 貢献者の質：2025 年のピークは 2022 年よりも堅実 <a class="header-anchor" href="#_1-1-貢献者の質-2025-年のピークは-2022-年よりも堅実" aria-label="Permalink to &quot;1.1 貢献者の質：2025 年のピークは 2022 年よりも堅実&quot;">​</a></h3><p><img src="'+d+'" alt="全体の月間アクティブ開発者 vs フルタイム開発者（2022–2026）"></p><table><thead><tr><th>時期</th><th>月間アクティブ開発者</th><th>フルタイム開発者</th><th>フルタイム比率</th></tr></thead><tbody><tr><td>2022-01</td><td>31,394</td><td>7,879</td><td>25.1%</td></tr><tr><td>2022-06</td><td>34,553</td><td>9,511</td><td>27.5%</td></tr><tr><td>2022-12</td><td>31,716</td><td>9,617</td><td>30.3%</td></tr><tr><td>2023-12</td><td>31,729</td><td>9,665</td><td>30.5%</td></tr><tr><td>2024-06</td><td>36,857</td><td>10,278</td><td>27.9%</td></tr><tr><td>2025-05</td><td>44,261</td><td>10,973</td><td>24.8%</td></tr><tr><td>2026-03</td><td>29,679</td><td>9,291</td><td>31.3%</td></tr></tbody></table><p>2025 年 5 月、月間アクティブ貢献者は過去最高の <strong>4.4 万人</strong> に達し、2022 年の強気相場期の高水準（3.5 万人）を上回った。2026 年初には約 <strong>2.97 万人</strong>（YoY -15%）まで調整したものの、フルタイム貢献者は 9,000 人超で比較的安定している。</p><p>重要なデータは、<strong>フルタイム貢献者の比率が 2022 年の 25% から 2026 年の 31% へ上昇した</strong> ことである。ここでいうフルタイム開発者／フルタイム貢献者は、毎月継続的にオープンソースリポジトリへコードを提出する中核的なメンテナーを指す。その比率の上昇は、Web3.0 オープンソースプロトコルの長期的なメンテナンス能力が強まっていることを意味する。市場サイクルによって全体の貢献者数が変動しても、プロトコルの基礎的な維持力は崩れていない。</p><blockquote><p><strong>インサイト 1</strong>：Web3.0 オープンソースプロトコルは、「話題性に駆動される段階」から「コアメンテナーの専門化」へと深い転換を進めている。弱気相場はふるいの役割を果たし、残ったのは真に長期的な担い手である。オープンソースプロトコルのレジリエンスは、市場に左右されず貢献を続けるこのフルタイム貢献者層に支えられている。</p></blockquote><hr><h2 id="第二章-中国語圏開発者のグローバルなオープンソースプロトコルにおける位置" tabindex="-1">第二章｜中国語圏開発者のグローバルなオープンソースプロトコルにおける位置 <a class="header-anchor" href="#第二章-中国語圏開発者のグローバルなオープンソースプロトコルにおける位置" aria-label="Permalink to &quot;第二章｜中国語圏開発者のグローバルなオープンソースプロトコルにおける位置&quot;">​</a></h2><p>主要な Web3.0 オープンソースプロトコルの貢献者リストでは、中国語名は非常に少ない。Ethereum クライアントのコアメンテナーであれ、Solana ランタイムの主要なコミッターであれ、中国語圏開発者はほとんど「見えにくい」存在である。しかし、この見えにくさは本当の不在を意味するのか、それとも統計方法による体系的な過小評価なのか。</p><h3 id="_2-1-グローバル-web3-0-開発者の国別分布-直近-1-年、地理記録あり" tabindex="-1">2.1 グローバル Web3.0 開発者の国別分布（直近 1 年、地理記録あり） <a class="header-anchor" href="#_2-1-グローバル-web3-0-開発者の国別分布-直近-1-年、地理記録あり" aria-label="Permalink to &quot;2.1 グローバル Web3.0 開発者の国別分布（直近 1 年、地理記録あり）&quot;">​</a></h3><p><img src="'+r+'" alt="グローバル Web3.0 国別分布 Top 10（月間アクティブ開発者）"></p><table><thead><tr><th>順位</th><th>国</th><th>アクティブ開発者</th><th>比率</th></tr></thead><tbody><tr><td>1</td><td>インド</td><td>4,768</td><td>28.1%</td></tr><tr><td>2</td><td>米国</td><td>3,645</td><td>21.5%</td></tr><tr><td>3</td><td>ナイジェリア</td><td>1,088</td><td>6.4%</td></tr><tr><td><strong>4</strong></td><td><strong>中国大陸</strong></td><td><strong>871</strong></td><td><strong>5.1%</strong></td></tr><tr><td>5</td><td>英国</td><td>852</td><td>5.0%</td></tr><tr><td>6</td><td>カナダ</td><td>763</td><td>4.5%</td></tr><tr><td>7</td><td>ブラジル</td><td>762</td><td>4.5%</td></tr><tr><td>8</td><td>ドイツ</td><td>733</td><td>4.3%</td></tr><tr><td>9</td><td>フランス</td><td>692</td><td>4.1%</td></tr><tr><td>10</td><td>インドネシア</td><td>674</td><td>4.0%</td></tr></tbody></table><blockquote><p>⚠️ <strong>統計上の落差について</strong>：上表のデータは、地理情報が記録されている約 27% の開発者のみに基づく。中国の開発者は GitHub に地理情報を記入する割合が欧米より著しく低く、中国語圏貢献者数は体系的に過小評価されている。GitHub Octoverse などのクロスデータを総合すると、中国語圏開発者（台湾、香港を含む）がグローバル Web3.0 オープンソースエコシステムに占める実際の比率は <strong>15-20%</strong> 近くに達する可能性があり、現在の統計値の 3-4 倍と見られる。</p></blockquote><h3 id="_2-2-ethereum-エコシステムの国・地域別分布-直近-1-年" tabindex="-1">2.2 Ethereum エコシステムの国・地域別分布（直近 1 年） <a class="header-anchor" href="#_2-2-ethereum-エコシステムの国・地域別分布-直近-1-年" aria-label="Permalink to &quot;2.2 Ethereum エコシステムの国・地域別分布（直近 1 年）&quot;">​</a></h3><p><img src="'+e+'" alt="Ethereum エコシステム国・地域別分布 Top 10（月間アクティブ開発者）"></p><table><thead><tr><th>順位</th><th>国・地域</th><th>開発者数</th><th>比率</th></tr></thead><tbody><tr><td>1</td><td>インド</td><td>2,830</td><td>38.8%</td></tr><tr><td>2</td><td>米国</td><td>1,797</td><td>24.7%</td></tr><tr><td>3</td><td>中国大陸</td><td>496</td><td>6.8%</td></tr><tr><td>4</td><td>英国</td><td>415</td><td>5.7%</td></tr><tr><td>5</td><td>ブラジル</td><td>391</td><td>5.4%</td></tr><tr><td>付録</td><td>台湾</td><td>116</td><td>1.6%</td></tr><tr><td>付録</td><td>香港</td><td>84</td><td>1.2%</td></tr></tbody></table><p><em>台湾、香港は付録データであり、順位には含めない</em></p><p>中国大陸は 3 位（496 人、6.8%）である。台湾（116 人）と香港（84 人）を合算すると、中国語圏合計は <strong>9.6%</strong> となり、Ethereum エコシステムにおける第 3 の言語圏グループとなる。</p><p><strong>出典による確認</strong>：『2025 Web3.0 中国語圏開発者調査レポート』は、「見えにくさ」の根本原因を示している。最も重要な可視性のハードルは、英語で協働する能力である。中国語圏開発者の大多数は英語ドキュメントを独力で読めるが、国際的なプロトコル開発で PR Review（プルリクエストのレビュー）に円滑に参加したり、RFC（Request for Comments、プロトコルや仕様の提案・議論文書）を提出したり、コアプロトコルの議論に参加したりできる割合はごく少ない。中国語圏開発者はしばしば「そこにいるが発言しない」状態にあり、コード貢献は実際に存在するものの、国際的なオープンソースコミュニティにおける発言力の蓄積が不足している。</p><blockquote><p><strong>インサイト 2</strong>：中国語圏開発者によるグローバル Web3.0 オープンソースプロトコルへの貢献は、大きく過小評価されている。そこには統計上の集計基準の問題と、実際の参加深度の不足という二つの要因がある。中国語圏コミュニティの国際的なオープンソースプロトコルにおける可視性を高めるには、開発者個人が英語での協働能力を高めることと、エコシステム運営側やコミュニティ組織が中国語の技術ドキュメントを積極的に整備し、貢献の入り口を下げることの両方が必要である。</p></blockquote><hr><h2 id="第三章-中国語圏開発者の主要オープンソースプロトコルにおける分布" tabindex="-1">第三章｜中国語圏開発者の主要オープンソースプロトコルにおける分布 <a class="header-anchor" href="#第三章-中国語圏開発者の主要オープンソースプロトコルにおける分布" aria-label="Permalink to &quot;第三章｜中国語圏開発者の主要オープンソースプロトコルにおける分布&quot;">​</a></h2><p>オープンソースプロトコルごとに中国語圏開発者を引きつける力は異なり、それは中国語圏コミュニティがどの技術路線を実際に選んでいるかを映し出す。どのプロトコルのコードベースに中国語圏貢献者が最も集中しているのか。中国語圏比率が高いプロトコルは、中国語ドキュメントやコミュニティ資源が比較的整っていることを意味する場合もあれば、逆に中国語圏コミュニティが早期からそのプロトコルの構築に深く関与してきたことを示す場合もある。</p><h3 id="中国語圏開発者の主要オープンソースプロトコルにおける貢献分布-直近-1-年" tabindex="-1">中国語圏開発者の主要オープンソースプロトコルにおける貢献分布（直近 1 年） <a class="header-anchor" href="#中国語圏開発者の主要オープンソースプロトコルにおける貢献分布-直近-1-年" aria-label="Permalink to &quot;中国語圏開発者の主要オープンソースプロトコルにおける貢献分布（直近 1 年）&quot;">​</a></h3><p><img src="'+o+'" alt="中国語圏開発者のエコシステム分布（中国大陸 vs 香港・台湾地域、月間アクティブ）"></p><table><thead><tr><th>エコシステム</th><th>中国大陸</th><th>香港・台湾地域</th><th>中国語圏合計</th><th>グローバル記録あり</th><th>中国語圏比率</th></tr></thead><tbody><tr><td>Ethereum</td><td>496</td><td>200</td><td>696</td><td>48,112</td><td><strong>1.4%</strong></td></tr><tr><td>Solana</td><td>269</td><td>71</td><td>340</td><td>26,543</td><td>1.3%</td></tr><tr><td>Sui</td><td>111</td><td>41</td><td>152</td><td>6,138</td><td><strong>2.5%</strong> ⬆️</td></tr><tr><td>Base</td><td>99</td><td>42</td><td>141</td><td>12,699</td><td>1.1%</td></tr><tr><td>BNB Chain</td><td>107</td><td>33</td><td>140</td><td>7,232</td><td>1.9%</td></tr><tr><td>Bitcoin</td><td>113</td><td>26</td><td>139</td><td>8,646</td><td>1.6%</td></tr><tr><td>Polygon</td><td>104</td><td>27</td><td>131</td><td>10,830</td><td>1.2%</td></tr><tr><td>Arbitrum</td><td>84</td><td>38</td><td>122</td><td>7,725</td><td>1.6%</td></tr><tr><td>Cosmos</td><td>34</td><td>10</td><td>44</td><td>2,032</td><td><strong>2.2%</strong></td></tr><tr><td>Starknet</td><td>24</td><td>8</td><td>32</td><td>3,561</td><td>0.9%</td></tr><tr><td>Stellar</td><td>12</td><td>0</td><td>12</td><td>5,546</td><td><strong>0.2%</strong> ⬇️</td></tr></tbody></table><p>ここでいう Move language はスマートコントラクト向けに設計されたプログラミング言語で、資産の安全な取り扱いを重視する。</p><p><strong>主な発見：</strong></p><ul><li><strong>Sui の中国語圏比率は 2.5%</strong> で、大型エコシステムの中で最も高く、Ethereum（1.4%）を約 1 倍上回る。Move 言語には中国語圏コミュニティ内で集積効果がある。</li><li><strong>Cosmos の中国語圏比率は 2.2%</strong> であり、Tendermint 時代からの中国語圏コミュニティの蓄積と関係している。</li><li><strong>BNB Chain の中国語圏比率は 1.9% にとどまる</strong>。中国語圏開発者の実際の貢献比率は、このチェーンの中国語圏コミュニティでの影響力とは一致していない。</li><li><strong>Stellar の中国語圏比率は 0.2%</strong> であり、中国語の技術ドキュメントとコミュニティ基盤はほぼ存在しない。</li></ul><p><strong>出典による確認</strong>：調査レポートによると、パブリックチェーンへの関心では Ethereum が大きく先行しており、Move 言語は「学ぶ価値のある第二外国語」として言及されている。これは Sui の中国語圏比率の高さとよく一致する。開発者の実際の行動（commit データ）とアンケート上の意向は整合している。</p><blockquote><p><em>図：中国語圏開発者のパブリックチェーン関心分布（出典：2025 Web3.0 中国語圏開発者調査レポート）</em><img src="'+a+'" alt="中国語圏開発者のパブリックチェーン関心度"></p></blockquote><blockquote><p><strong>インサイト 3</strong>：Sui エコシステムにおける中国語圏開発者比率の高さは、強みであると同時に責任でもある。中国語ドキュメント、チュートリアル、コミュニティ支援の深刻な不足は、早急に埋めるべき空白である。</p></blockquote><hr><h2 id="第四章-中国語圏コミュニティにおけるオープンソースプロトコル選択の移行-2021-2025" tabindex="-1">第四章｜中国語圏コミュニティにおけるオープンソースプロトコル選択の移行（2021-2025） <a class="header-anchor" href="#第四章-中国語圏コミュニティにおけるオープンソースプロトコル選択の移行-2021-2025" aria-label="Permalink to &quot;第四章｜中国語圏コミュニティにおけるオープンソースプロトコル選択の移行（2021-2025）&quot;">​</a></h2><p>この 5 年間、中国語圏開発者はどのオープンソースプロトコルに継続的に貢献してきたのか。この変化を示す図は、市場の選好だけではなく、中国語圏コミュニティがオープンソース技術路線に対して下してきた集団的な判断と移行の軌跡を記録している。</p><h3 id="中国語圏開発者による主要オープンソースプロトコルへの年次アクティブ貢献数-重複排除" tabindex="-1">中国語圏開発者による主要オープンソースプロトコルへの年次アクティブ貢献数（重複排除） <a class="header-anchor" href="#中国語圏開発者による主要オープンソースプロトコルへの年次アクティブ貢献数-重複排除" aria-label="Permalink to &quot;中国語圏開発者による主要オープンソースプロトコルへの年次アクティブ貢献数（重複排除）&quot;">​</a></h3><p><img src="'+n+'" alt="主要エコシステムにおける中国語圏開発者数の変化（2021–2025）"></p><table><thead><tr><th>年</th><th>Ethereum</th><th>Solana</th><th>BNB Chain</th><th>Sui</th><th>Bitcoin</th><th>TON</th><th>Aptos</th></tr></thead><tbody><tr><td>2021</td><td>252</td><td>139</td><td>86</td><td>8</td><td>49</td><td>5</td><td>13</td></tr><tr><td>2022</td><td>528</td><td>201</td><td><strong>160</strong></td><td>57</td><td>47</td><td>17</td><td>84</td></tr><tr><td>2023</td><td>425</td><td>149</td><td>120</td><td>90</td><td>72</td><td>35</td><td>63</td></tr><tr><td>2024</td><td>446</td><td><strong>334</strong></td><td>74</td><td><strong>204</strong></td><td>107</td><td>99</td><td>69</td></tr><tr><td>2025</td><td><strong>670</strong></td><td>352</td><td>132</td><td>170</td><td>139</td><td>44</td><td>65</td></tr></tbody></table><p><strong>四つの重要な曲線：</strong></p><p><strong>BNB Chain のオープンソース貢献の減退</strong>：アクティブ貢献者は 2022 年のピーク 160 人から 2024 年には 74 人へ減少した（<strong>-54%</strong>）。データは、BNB Chain のオープンソースプロトコルのメンテナンス活動が、中国語圏コミュニティの継続的な参加を支えきれなかったことを示している。貢献データと外部の語られ方との間には、明確な落差がある。</p><p><strong>Solana オープンソースコミュニティの V 字回復</strong>：2023 年の市場イベントの影響で貢献者は 149 人まで落ち込んだが、2024 年には 334 人へ反発した（+<strong>124%</strong>）。Solana のオープンソースコミュニティが低迷期にもコアリポジトリの維持を続けたことが、中国語圏貢献者を再び引きつける鍵となった。技術路線への継続的な投資は、市場センチメントよりも強い説得力を持つ。</p><p><strong>Sui プロトコルにおける中国語圏貢献者の継続的成長</strong>：2021 年の 8 人から 2024 年には 204 人へ増加した（<strong>+2450%</strong>）。Move 言語は新しいスマートコントラクトのパラダイムとして、中国語圏コミュニティがプロトコル初期から大規模に参加した領域であり、一時的な話題による流入ではなく、継続的な貢献の蓄積を形成している。</p><p><strong>TON 貢献者の一過性の急増</strong>：2024 年に 99 人まで急増した後、44 人へ急速に戻った。貢献者は話題性に従って流入したが、TON のオープンソースプロトコルはドキュメント品質、ツールチェーンの成熟度、コミュニティの応答速度の面で彼らを引き留めきれなかった。このことは、「話題性に駆動された参加」そのものの限界を裏付けている。</p><p><strong>出典による確認</strong>：調査レポートは、中国語圏開発者がプロトコルを選ぶ際の中核的な判断材料として、エコシステムの規模と機会、技術路線の長期性、中国語コミュニティ支援の品質を挙げている。中国語ドキュメントとオープンソースコミュニティ支援の品質は、中国語圏開発者があるプロトコルで継続的に貢献を積み上げられるかに直接影響する。</p><blockquote><p><strong>インサイト 4</strong>：中国語圏開発者によるオープンソースプロトコルの選択は、エコシステムのオープンソース健全性を示す先行指標である。あるプロトコルが中国語圏貢献者を定着させられるかどうかの核心は、技術路線に長期的価値があること、低迷期にもオープンソースコミュニティが維持を続けること、中国語ドキュメントと貢献パスが明確に見えることにある。</p></blockquote><hr><h2 id="第五章-中国大陸のオープンソース貢献者の都市分布" tabindex="-1">第五章｜中国大陸のオープンソース貢献者の都市分布 <a class="header-anchor" href="#第五章-中国大陸のオープンソース貢献者の都市分布" aria-label="Permalink to &quot;第五章｜中国大陸のオープンソース貢献者の都市分布&quot;">​</a></h2><p>Web3.0 オープンソース貢献者の空間分布は、中国のオープンソースエコシステムの地域構造を映し出している。Web3.0 プロトコルへ継続的に貢献する開発者は、どの都市に最も集まっているのか。</p><h3 id="web3-0-オープンソース貢献者の都市-top-10-直近-1-年、地理記録あり" tabindex="-1">Web3.0 オープンソース貢献者の都市 Top 10（直近 1 年、地理記録あり） <a class="header-anchor" href="#web3-0-オープンソース貢献者の都市-top-10-直近-1-年、地理記録あり" aria-label="Permalink to &quot;Web3.0 オープンソース貢献者の都市 Top 10（直近 1 年、地理記録あり）&quot;">​</a></h3><p><img src="'+s+'" alt="中国都市別 Web3.0 アクティブ開発者分布 Top 10"></p><table><thead><tr><th>順位</th><th>都市</th><th>アクティブ開発者</th><th>中国語圏合計に占める比率</th></tr></thead><tbody><tr><td>1</td><td>北京</td><td>171</td><td>12.4%</td></tr><tr><td>2</td><td>上海</td><td>168</td><td>12.2%</td></tr><tr><td>3</td><td>杭州</td><td>99</td><td>7.2%</td></tr><tr><td>4</td><td>深圳</td><td>94</td><td>6.8%</td></tr><tr><td>5</td><td>成都</td><td>44</td><td>3.2%</td></tr><tr><td>6</td><td>広州</td><td>32</td><td>2.3%</td></tr><tr><td>7</td><td>武漢</td><td>18</td><td>1.3%</td></tr><tr><td>8</td><td>南京</td><td>15</td><td>1.1%</td></tr><tr><td>9</td><td>西安</td><td>11</td><td>0.8%</td></tr><tr><td>10</td><td>厦門</td><td>10</td><td>0.7%</td></tr></tbody></table><p><strong>注目すべき三つの現象：</strong></p><p><strong>単極ではなく二大中心</strong>：北京（171）と上海（168）はほぼ同水準で、合計しても約 24.6% にとどまる。従来のインターネット産業に見られる「北京・上海・深圳の合計が 75% 超」という集中度を大きく下回る。Web3.0 オープンソース貢献の分散的な性質は、地理的分布の分散にも実際に反映されている。</p><p><strong>杭州が深圳を上回る</strong>：杭州は 99 人で深圳（94 人）を上回り、3 位となった。杭州には、登链学院や複数の EVM（Ethereum Virtual Machine、Ethereum 互換スマートコントラクト実行環境）ツールチェーンのメンテナンスチームなど、活発なブロックチェーン技術オープンソースコミュニティがある。さらに浙江大学系のエンジニア文化もあり、比較的強いオープンソース貢献の雰囲気が形成されている。</p><p><strong>成都は西部のオープンソース貢献中心</strong>：成都は 44 人で西部地域の首位を安定して維持している。Dapp-Learning、HOH などの活発な中国語圏 Web3.0 オープンソース学習コミュニティが成都に重要な拠点を持っている。このような「学習を通じて貢献を促す」オープンソースコミュニティのモデルは、成都にオープンソース貢献者が集まる重要な理由である。</p><p><strong>出典による確認</strong>：調査レポートは「地理的アービトラージ」という現象を示している。多くの開発者が二線都市に住むことを選び、中国国内の生活コストを基準にしながら、米ドルまたはステーブルコインで報酬を受け取り、実質的な購買力を最大化している。これは、Web3.0 の都市分布がインターネット産業よりはるかに均等である理由を説明する。働く場所が雇用主の都市と一致しなくなると、開発者は生活コスト、住みやすさ、コミュニティ密度のバランスをより合理的に選ぶようになる。</p><blockquote><p><em>図：中国語圏開発者の地理分布（出典：2025 Web3.0 中国語圏開発者調査レポート）</em><img src="'+l+'" alt="中国語圏開発者の地理分布"></p></blockquote><blockquote><p><strong>インサイト 5</strong>：Web3.0 のリモート協働文化は、中国の開発者の空間分布を作り変えつつある。杭州、成都、武漢などの都市は新たな Web3.0 人材の集積地になりつつあり、「北京・上海・深圳」による技術人材の独占性は弱まりつつある。</p></blockquote><hr><h2 id="第六章-主要-web3-0-オープンソースプロトコルの貢献者健全性-2026-03" tabindex="-1">第六章｜主要 Web3.0 オープンソースプロトコルの貢献者健全性（2026-03） <a class="header-anchor" href="#第六章-主要-web3-0-オープンソースプロトコルの貢献者健全性-2026-03" aria-label="Permalink to &quot;第六章｜主要 Web3.0 オープンソースプロトコルの貢献者健全性（2026-03）&quot;">​</a></h2><p>オープンソースプロトコルの健全性を測るには、貢献者の総数だけでは不十分である。貢献者の構成、すなわちフルタイムメンテナーの比率（長期的な持続可能性）、新規貢献者の流入（エコシステムの活力）、貢献者の専属性（コミュニティへの定着度）を見る必要がある。下表は、15 の主要 Web3.0 オープンソースプロトコルについて、六つの観点から貢献者の健全性を切り出したスナップショットである。</p><h3 id="主要オープンソースプロトコルの貢献者健全性の概観" tabindex="-1">主要オープンソースプロトコルの貢献者健全性の概観 <a class="header-anchor" href="#主要オープンソースプロトコルの貢献者健全性の概観" aria-label="Permalink to &quot;主要オープンソースプロトコルの貢献者健全性の概観&quot;">​</a></h3><table><thead><tr><th>エコシステム</th><th>月間アクティブ開発者</th><th>YoY</th><th>フルタイム比率</th><th>新規比率</th><th>専属比率</th><th>中国語圏比率*</th></tr></thead><tbody><tr><td>Ethereum</td><td>10,926</td><td>-23%</td><td>33%</td><td>38%</td><td>45%</td><td>1.4%</td></tr><tr><td>Solana</td><td>3,904</td><td>-26%</td><td>29%</td><td>45%</td><td>49%</td><td>1.3%</td></tr><tr><td>Bitcoin</td><td>2,941</td><td>-15%</td><td>33%</td><td>39%</td><td>56%</td><td>1.6%</td></tr><tr><td><strong>Base</strong></td><td><strong>2,525</strong></td><td><strong>+25%</strong></td><td>23%</td><td><strong>52%</strong></td><td>20%</td><td>1.1%</td></tr><tr><td>Polygon</td><td>2,032</td><td>+3%</td><td>27%</td><td>49%</td><td>19%</td><td>1.2%</td></tr><tr><td>Arbitrum</td><td>1,829</td><td>+1%</td><td>26%</td><td>43%</td><td>15%</td><td>1.6%</td></tr><tr><td><strong>ICP</strong></td><td><strong>1,661</strong></td><td><strong>+83%</strong></td><td>11%</td><td><strong>82%</strong></td><td><strong>91%</strong></td><td>0.7%</td></tr><tr><td>Cosmos</td><td>1,449</td><td>-37%</td><td>26%</td><td>29%</td><td>47%</td><td>2.2%</td></tr><tr><td><strong>Stellar</strong></td><td><strong>1,218</strong></td><td><strong>+40%</strong></td><td>20%</td><td>49%</td><td>57%</td><td>0.2%</td></tr><tr><td>Polkadot</td><td>1,090</td><td>-34%</td><td>34%</td><td>25%</td><td>42%</td><td>1.7%</td></tr><tr><td>BNB Chain</td><td>1,074</td><td>-24%</td><td>25%</td><td>44%</td><td>19%</td><td>1.9%</td></tr><tr><td>Optimism</td><td>1,065</td><td>-13%</td><td>22%</td><td>39%</td><td>13%</td><td>1.5%</td></tr><tr><td>Sui</td><td>940</td><td>-20%</td><td>30%</td><td>36%</td><td>45%</td><td><strong>2.5%</strong></td></tr><tr><td>Starknet</td><td>764</td><td>-41%</td><td>24%</td><td>35%</td><td>35%</td><td>0.9%</td></tr><tr><td>TON</td><td>550</td><td>-29%</td><td>27%</td><td>37%</td><td>50%</td><td>1.3%</td></tr></tbody></table><p>*中国語圏比率は地理情報が記録されているサブセットに基づくため、実際の値はさらに高い可能性がある</p><p><img src="'+i+'" alt="主要エコシステムの YoY 成長率（2026-03）"></p><h3 id="この表の読み方" tabindex="-1">この表の読み方 <a class="header-anchor" href="#この表の読み方" aria-label="Permalink to &quot;この表の読み方&quot;">​</a></h3><p><strong>逆風下で成長した五つのプロトコル</strong>：ICP(+83%)、Stellar(+40%)、Base(+25%)、Polygon(+3%)、Arbitrum(+1%)。全体の貢献者数が調整する中で、この五つのプロトコルは新規貢献者の純流入を獲得しており、オープンソースエコシステムにはなお実際の開発需要があることを示している。</p><p><strong>ICP の懸念点</strong>：+83% YoY である一方、新規比率は 82%、専属率は 91% に達し、他プロトコルから移ってきた経験ある貢献者はほとんどいない。急成長の背後で、コミュニティの知識蓄積の深さはまだ検証が必要である。中国語圏比率は 0.7% にとどまり、中国語の貢献ガイドはほぼ存在せず、埋めるべき空白となっている。</p><p><strong>Base の健全なシグナル</strong>：+25% YoY、新規比率 52%、専属率はわずか 20%。EVM でのオープンソース経験を持つ多くの開発者が Base でも同時に活動しており、新旧の貢献者が併存している。これはオープンソースエコシステムが健全に拡張している理想的な状態である。</p><p><strong>出典による確認</strong>：調査レポートでは、開発者は「エコシステム内の機会密度」（Grant、Bounty、プロダクト需要）を、オープンソースプロトコルへの参加を選ぶ際の最重要要因として挙げている。これは純粋な技術的先進性よりも重視されている。Grant（プロトコルや財団などによる開発助成）、Bounty（特定タスクに対する報酬付き募集）といったオープンソースインセンティブの整備度は、中国語圏貢献者の参加意欲に直接影響する。</p><blockquote><p><em>図：中国語圏開発者が Web3.0 に入った主な動機（出典：2025 Web3.0 中国語圏開発者調査レポート）</em><img src="'+h+'" alt="中国語圏開発者の参入動機"></p></blockquote><blockquote><p><strong>インサイト 6</strong>：Web3.0 オープンソースプロトコルの貢献者健全性は、急速に分化している。あるプロトコルが長期的に取り組む価値を持つかどうかを測る重要指標は、規模ではなく貢献者構成である。すなわち、フルタイム貢献者比率（長期的な持続可能性）、新規貢献者の流入（活力）、クロスプロトコル貢献者の比率（開放性）である。中国語圏オープンソースコミュニティにとって、Sui（中国語圏貢献者比率が最も高く、中国語の知識基盤を必要としている）、Base（貢献のハードルが低く、EVM の汎用スキルを移転しやすい）、ICP（中国語の貢献ガイドがほぼ存在せず、空白がある）は、それぞれ異なる三つの取り組み口を代表している。</p></blockquote><hr><h2 id="第七章-中国語圏開発者のオープンソース貢献の現状" tabindex="-1">第七章｜中国語圏開発者のオープンソース貢献の現状 <a class="header-anchor" href="#第七章-中国語圏開発者のオープンソース貢献の現状" aria-label="Permalink to &quot;第七章｜中国語圏開発者のオープンソース貢献の現状&quot;">​</a></h2><p>Web3.0 エコシステムはオープンソースプロトコルの上に成り立っているが、「オープンソースを使うこと」と「オープンソースに貢献すること」の間には大きな隔たりがある。中国語圏コミュニティが Web3.0 オープンソースエコシステムにどの程度深く貢献しているかを理解することは、本レポートが中国オープンソース年度報告に提供する最も中核的な価値である。</p><h3 id="_7-1-依存度は高いが、参加の深さは不足している" tabindex="-1">7.1 依存度は高いが、参加の深さは不足している <a class="header-anchor" href="#_7-1-依存度は高いが、参加の深さは不足している" aria-label="Permalink to &quot;7.1 依存度は高いが、参加の深さは不足している&quot;">​</a></h3><p>『2025 Web3.0 中国語圏開発者調査レポート』は、典型的な「ただ乗り構造」を明らかにしている。ほぼすべての中国語圏 Web3.0 開発者がオープンソースコンポーネントに強く依存している一方で、実際にプロジェクトを長期的に維持するコア貢献者は非常に少ない。</p><ul><li><strong>Issue を出す人は多いが、PR を出す人は少ない</strong>：コードを読み、問題を見つけられる開発者は、修正を提出できる開発者よりはるかに多い。</li><li><strong>主な参加動機</strong>：学習とスキル向上が最上位であり、次に自分が直面した問題の解決が続く。</li><li><strong>主な阻害要因</strong>：時間不足、参加パスの不明瞭さ、適切な入門プロジェクトが見つからないこと、英語での協働能力の不足。</li></ul><blockquote><p><em>図：中国語圏開発者による Web3.0 コアリポジトリへの貢献アクティビティ（出典：2025 Web3.0 中国語圏開発者調査レポート）</em><img src="'+p+'" alt="中国語圏開発者のコアリポジトリ貢献アクティビティ"></p></blockquote><p>この現象の背後には、<strong>中国語の技術知識基盤が長期的に不足してきたこと</strong> がある。質の高い中国語のプロトコルドキュメント、初学者向けの貢献ガイド、活発な中国語技術ディスカッションコミュニティは、中国語圏開発者が「利用者」から「貢献者」へ成長するための必要条件である。</p><h3 id="_7-3-web3-0-オープンソースインセンティブメカニズムの新たな実験" tabindex="-1">7.3 Web3.0 オープンソースインセンティブメカニズムの新たな実験 <a class="header-anchor" href="#_7-3-web3-0-オープンソースインセンティブメカニズムの新たな実験" aria-label="Permalink to &quot;7.3 Web3.0 オープンソースインセンティブメカニズムの新たな実験&quot;">​</a></h3><p>Web3.0 は、Grant、Bounty、Token 報酬、オンチェーンレピュテーションシステムを用いて、オープンソース貢献のインセンティブ構造を再設計しようとしている。これは、グローバルな開発者、そして中国語圏開発者に対して、従来のオープンソースにおける「自発的貢献」モデルを超える新たな道を提供する。現時点ではこれらの仕組みはまだ実験段階にあるが、方向性として注目に値する。</p><ul><li><strong>Grant プログラム</strong>（Ethereum Foundation、Solana Foundation など）：独立開発者やチームに対し、プロトコルレベルの貢献に向けた助成を提供する。</li><li><strong>Bounty プラットフォーム</strong>（Gitcoin など）：具体的なニーズを有償タスクに変換し、貢献の入り口を下げる。</li><li><strong>オンチェーンレピュテーション</strong>：貢献記録をチェーン上に記録し、検証可能な技術的信用を積み上げる。</li></ul><blockquote><p><strong>インサイト 7</strong>：中国語圏コミュニティの Web3.0 オープンソースエコシステムにおける弱点は、技術力ではなく、参加パスの見えやすさにある。高品質な中国語技術ドキュメントを整備すること、初級貢献者に明確な入門ガイドを提供すること、Grant/Bounty 情報の中国語での到達率を高めることは、中国のオープンソースコミュニティがグローバルな Web3.0 エコシステムに対して行える最も直接的な貢献である。</p></blockquote><hr><h2 id="第八章-提言と展望" tabindex="-1">第八章｜提言と展望 <a class="header-anchor" href="#第八章-提言と展望" aria-label="Permalink to &quot;第八章｜提言と展望&quot;">​</a></h2><p>Web3.0 オープンソースエコシステムへの中国語圏の参加は、初期の「追随者」段階から、無視できない力へと変化している。中国語圏開発者は規模の面で世界第 2 の言語圏グループであり、一部のプロトコル（Sui、Cosmos）では貢献比率がグローバル平均を上回っている。しかし、「規模」から「影響力」へ進むには、なお明確なギャップを埋める必要がある。</p><h3 id="_8-1-開発者個人への提言" tabindex="-1">8.1 開発者個人への提言 <a class="header-anchor" href="#_8-1-開発者個人への提言" aria-label="Permalink to &quot;8.1 開発者個人への提言&quot;">​</a></h3><p><strong>話題を追って広く浅く触れるのではなく、中国語コミュニティに支えられたプロトコルを選んで深く取り組む</strong></p><p>データは、中国語圏開発者が Sui（2.5%）、Cosmos（2.2%）など、成熟した中国語コミュニティを持つプロトコルで有意に高い貢献比率を示していることを明らかにしている。中国語ドキュメント、活発な議論コミュニティ、明確な貢献パスを持つプロトコルを一つ選び、体系的に貢献を積み上げることは、毎回の話題に合わせて最初から学び直すよりも長期的なリターンが大きい。</p><p><strong>「Issue を出す」から「PR を出す」へ進む</strong></p><p>調査データによると、中国語圏開発者のオープンソース参加は、一般に「問題を見つける」段階にとどまり、「問題を修正する」段階には進めていない。Dapp-Learning、letsmove など、組織化された貢献パスを持つ学習コミュニティに参加することは、「読者」から「貢献者」へ進む最も低コストな道である。二つのリポジトリは合計 3,700 件超の PR を蓄積しており、このパスが実行可能であることを示している。</p><p><strong>英語での協働能力は可視性の基礎的なハードルである</strong></p><p>中国語圏開発者が「そこにいるが発言しない」問題について、短期的に最も実行可能な改善策は、エコシステム運営側が中国語インターフェースを提供するのを待つことではなく、英語の PR Review と技術議論に主体的に参加することである。これは、中国語圏貢献者が「コード貢献者」から「プロトコルに影響を与える人」へ成長するために避けて通れない道である。</p><h3 id="_8-2-オープンソースコミュニティとエコシステム運営側への提言" tabindex="-1">8.2 オープンソースコミュニティとエコシステム運営側への提言 <a class="header-anchor" href="#_8-2-オープンソースコミュニティとエコシステム運営側への提言" aria-label="Permalink to &quot;8.2 オープンソースコミュニティとエコシステム運営側への提言&quot;">​</a></h3><p><strong>一度きりの翻訳ではなく、中国語の知識基盤を体系的に整備する</strong></p><p>中国語圏開発者が新しいプロトコルに入る際の最大のハードルは、技術的な難しさではなく、「信頼できる中国語の入門資料が見つからないこと」である。Ethereum 中国語ドキュメント（ethereum.org/zh）は、現在数少ない体系的なメンテナンスを実現している事例である。より多くのプロトコル（ICP、Stellar、Polkadot）では、中国語の貢献ガイドがほぼ存在しない。これは、オープンソースコミュニティが直接関与できる空白である。</p><p><strong>「トレーニングキャンプ」と「オープンソース貢献」を体系的につなげる</strong></p><p>OpenBuild、登链学院などのプラットフォームは、「トレーニングキャンプ修了 = PR 提出」というモデルの実行可能性をすでに検証している。OpenBuild の 9 つのトレーニングキャンプリポジトリは、6 つのエコシステムにまたがる 665 件超の独立した貢献記録を蓄積している。WTF Academy は、オープンソース教材の形で Solidity と複数の Web3.0 基礎スタックをカバーし、GitHub の貢献者体系も成熟しており、技術入門からオープンソース貢献への転換においてハードルが低いルートの一つである。706 Creators と LXDAO は別のモデルを示している。コミュニティでの共同学習を中心に、学習プロセスそのものを組織化し、参加者が協働の中で自然にオープンソース貢献の習慣を形成できるようにするもので、外部インセンティブだけに依存しない。こうした異なるパスのモデルをより多くのプロトコルエコシステムへ広げることは、中国語圏コミュニティがグローバルな Web3.0 オープンソースに貢献者を送り出すうえで、最も効率的な方法である。</p><p><strong>Grant と Bounty 情報の中国語到達率を高める必要がある</strong></p><p>調査データによると、中国語圏開発者は「エコシステム内の機会密度」をオープンソース参加の最重要判断材料としている。しかし Ethereum Foundation Grant、Solana Foundation Grant などの中核的な助成プログラムは、中国語での情報到達率が非常に低い。エコシステム運営側と中国語圏コミュニティ組織が常設の情報同期メカニズムを作ることは、中国語圏貢献者の参加転換率を直接高めうる。注目すべき点として、GCC（Global Chinese Community of Universal Digital Commons）は、中国語圏コミュニティ内で Web3.0 オープンソースプロジェクト向けの公共財寄付メカニズムをすでに構築しており、累計 45 件超のプロジェクトを助成している。これは、中国語圏開発者がオープンソースプロジェクトの資金支援を求める際のローカルなチャネルの一つである。</p><h3 id="_8-3-展望" tabindex="-1">8.3 展望 <a class="header-anchor" href="#_8-3-展望" aria-label="Permalink to &quot;8.3 展望&quot;">​</a></h3><p>2026 年の Web3.0 オープンソースエコシステムは、弱気相場による淘汰後の「コア貢献者の時代」に入っている。フルタイム貢献者比率は過去最高を記録し、投機目的の参加者は退出した。残っているのは、技術の長期的価値に真に関心を持つ開発者である。これは中国語圏オープンソースコミュニティにとって得がたい機会である。喧騒が退いた後、プロトコル基盤への継続的な貢献に集中することこそ、長期的な発言力を蓄積する最良のタイミングである。</p><p>中国語圏コミュニティが Web3.0 オープンソースエコシステムで次の段階へ進むために必要なのは、中国語圏向けのパブリックチェーンをもう一つ作ることではない。<strong>グローバルに技術的合意が形成されているオープンソースプロトコルの上で、代替できない中国語の知識基盤の整備者、そしてコアプロトコル貢献者になること</strong> である。</p><blockquote><p><strong>インサイト 8</strong>：中国語圏開発者によるグローバル Web3.0 オープンソースエコシステムへの貢献は、「参加者の規模」から「基盤を整備する担い手」へと転換しつつある。中国語技術ドキュメント、貢献者育成パス、Grant 情報の到達、この三つの「知識基盤」の整備品質が、次の Web3.0 オープンソースサイクルにおける中国語圏コミュニティの発言力の深さを決める。</p></blockquote><hr><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>Electric Capital のオープンソース開発者データを見ると、2026 年初の Web3.0 エコシステムは重要な節目にある。グローバルな月間アクティブ貢献者は 2025 年のピークから約 33% 調整したが、フルタイム貢献者比率は過去最高を記録している。バブルが整理された後に残ったのは、真に長期的なオープンソースの担い手である。</p><p>中国のオープンソースコミュニティにとって、Web3.0 には正面から受け止めるべき三つの現実がある。</p><ol><li><strong>貢献規模は体系的に過小評価されている</strong>：中国語圏 Web3.0 オープンソース貢献者の実際の規模は、統計値の 3-4 倍である可能性がある。しかし、国際的なオープンソースプロトコルコミュニティにおける発言力は、貢献規模と大きく釣り合っていない。</li><li><strong>プロトコル選択は成熟しつつある</strong>：中国語圏コミュニティは、初期の話題性駆動（BNB Chain）から、より成熟した技術選択（Ethereum、Solana、Sui）へ移行しており、オープンソース貢献の長期性は強まっている。</li><li><strong>地理分布は分散している</strong>：オープンソースのリモート協働文化は、貢献者を北京・上海・深圳から全国へ広げており、ローカルなオープンソースコミュニティの整備が地域のオープンソースエコシステムの中核的な推進力になっている。</li></ol><p>中国のオープンソースコミュニティが Web3.0 のグローバルプロトコル構築に深く参加する最大の機会は、別の閉じたエコシステムを一から構築することではない。<strong>グローバルに技術的合意が形成されているオープンソースプロトコルの上で、中国語圏コミュニティの知識基盤を体系的に整備すること</strong> にある。高品質な中国語プロトコルドキュメント、明確な貢献者向け入門ガイド、活発な中国語技術ディスカッションコミュニティは、中国語圏開発者を「利用者」から「コア貢献者」へ転換するための重要なパスである。</p>',135)])])}const y=b(m,[["render",q]]);export{x as __pageData,y as default};
